import json, collections
# build ownership map
def load(f): return [json.loads(l) for l in open('/tmp/exp/'+f+'.ndjson')]
def ext(r,n):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+n):
            for k,v in e.items():
                if k.startswith('value'): return v
owner={}
nosub=set()
for t in ['Patient','EpisodeOfCare','Condition','Observation','Specimen','MedicationAdministration','MedicationDispense','DocumentReference','AllergyIntolerance','Task']:
    for r in load(t):
        if t=='Patient': owner[r['id']]=r['id']; continue
        s=r.get('subject') or r.get('patient') or r.get('for')
        owner[r['id']]=s['reference'].split('/')[1] if s else None
for b in load('Basic'): owner[b['id']]=None; nosub.add(b['id'])
# links via labs
spec={s['id']:s for s in load('Specimen')}
pats={p['id']:p for p in load('Patient')}
key2p={(p['identifier'][0]['value'],p['birthDate']):p['id'] for p in pats.values()}
accm={ext(b,'accession'):b for b in load('Basic')}
links=collections.defaultdict(set)
for o in load('Observation'):
    ps={o['subject']['reference'].split('/')[1]}
    sr=(o.get('specimen') or {}).get('reference')
    s=spec.get(sr.split('/')[-1]) if sr else None
    if s:
        ps.add(s['subject']['reference'].split('/')[1])
        k=key2p.get((ext(s,'label-mrn'),str(ext(s,'label-dob'))))
        if k: ps.add(k)
    an=o.get('identifier',[{}])[0].get('value'); b=accm.get(an)
    if b:
        k=key2p.get((ext(b,'patient-mrn'),str(ext(b,'patient-dob'))))
        if k: ps.add(k)
    for a in ps:
        links[a]|=ps
bad=[]
for x in json.load(open('/tmp/items.json')):
    p=x['patient']; allowed={p}|links.get(p,set())
    for rid in x['evidence']:
        r=rid.split('/')[-1]
        if r not in owner: bad.append((p,rid,'UNKNOWN'))
        elif owner[r] is None: pass
        elif owner[r] not in allowed: bad.append((p,rid,owner[r]))
print('bad evidence:',bad[:20], len(bad))
